-- READ ONLY: 172.17.90.178:13306/npdms
-- Generated from MyBatis XML and tenant interceptor; tenant=1, existing super_admin view, page 1/10.
-- Review and SQL verification only. Runtime must prepare identity and scope through Owner APIs.
-- No DDL, business DML, migration or persistent temporary objects.
WITH project_scope_nodes AS (SELECT t.root_project_id, t.tree_version, t.descendant_project_id AS project_id FROM proj_project_tree_path t WHERE t.tenant_id = 1 AND t.deleted = B'0' AND t.ancestor_project_id = t.root_project_id AND 1 = 0 AND t.tenant_id = 1), project_scope_grants AS (SELECT NULL AS resource_id, NULL AS scope_code WHERE 1 = 0), visible_projects AS (SELECT DISTINCT p.id AS project_id FROM proj_project p WHERE p.tenant_id = 1 AND p.deleted = B'0' AND p.tenant_id = 1), device_filter_contract_keys AS (SELECT NULL AS contract_key WHERE 1 = 0), unique_device_contracts AS (SELECT MAX(id) AS id, MAX(tenant_id) AS tenant_id, contract_no, MAX(company_code) AS company_code FROM com_contract WHERE tenant_id = 1 AND deleted = B'0' AND tenant_id = 1 GROUP BY contract_no HAVING COUNT(*) = 1), visible_device_contracts AS (SELECT DISTINCT CAST(c.contract_no AS BINARY) AS contract_key FROM unique_device_contracts c WHERE c.tenant_id = 1 AND c.contract_no IS NOT NULL AND c.contract_no <> '' AND NOT EXISTS (SELECT 1 FROM com_shipment_contract_reference shipment WHERE shipment.tenant_id = c.tenant_id AND shipment.deleted = B'0' AND shipment.contract_no = c.contract_no AND (shipment.company_code IS NULL OR shipment.company_code = '' OR CAST(shipment.company_code AS BINARY) <> CAST(c.company_code AS BINARY)) AND shipment.tenant_id = 1) AND (EXISTS (SELECT 1 FROM com_project_contract_relation pcr JOIN visible_projects vp ON vp.project_id = pcr.project_id WHERE pcr.tenant_id = c.tenant_id AND pcr.contract_id = c.id AND pcr.deleted = B'0' AND pcr.status = 'ACTIVE' AND pcr.effective_to IS NULL AND pcr.tenant_id = 1))), visible_direct_projects AS (SELECT DISTINCT d.project_id FROM ast_device d JOIN visible_projects vp ON vp.project_id = d.project_id WHERE d.tenant_id = 1 AND d.deleted = B'0' AND d.project_id IS NOT NULL AND d.tenant_id = 1), visible_related_devices AS (SELECT DISTINCT r.device_sn FROM ast_device_project_relationship r JOIN visible_projects vp ON vp.project_id = r.project_id WHERE r.tenant_id = 1 AND r.deleted = B'0' AND r.effective_from <= CURRENT_TIMESTAMP(3) AND (r.effective_to IS NULL OR r.effective_to > CURRENT_TIMESTAMP(3)) AND r.tenant_id = 1), device_totals AS (SELECT COUNT(*) AS total FROM ast_device d WHERE d.tenant_id = 1 AND d.deleted = B'0' AND (1 = 0 OR (EXISTS (SELECT 1 FROM visible_direct_projects) AND d.project_id IN (SELECT project_id FROM visible_direct_projects)) OR (EXISTS (SELECT 1 FROM visible_related_devices) AND d.sn IN (SELECT device_sn FROM visible_related_devices)) OR (EXISTS (SELECT 1 FROM visible_device_contracts) AND CAST(d.contract_no AS BINARY) IN (SELECT contract_key FROM visible_device_contracts))) AND d.tenant_id = 1), device_page AS (SELECT d.id AS device_id, d.sn, d.name, d.status, d.product_code, d.product_model, d.product_name, d.shipment_time, d.package_no, d.contract_no, d.shipment_record_id, d.project_id, d.customer_id, d.warranty_start_date, d.warranty_end_date, d.warranty_status, d.conp_version, d.conp_type, d.conp_series, d.conp_mark, d.sync_status, d.location_snapshot, d.location_resolution_status, d.company_id, d.company_name, d.department_id, d.department_code, d.department_name, d.organization_source, nv.boot_version, nv.cpld_version FROM ast_device d LEFT JOIN ast_device_network_version nv ON nv.tenant_id = d.tenant_id AND nv.device_sn = d.sn AND nv.deleted = B'0' AND nv.source_system = 'DEVICE_LOG' AND (nv.sync_status IS NULL OR nv.sync_status <> 'NOT_AVAILABLE') AND nv.tenant_id = 1 WHERE d.tenant_id = 1 AND d.deleted = B'0' AND (1 = 0 OR (EXISTS (SELECT 1 FROM visible_direct_projects) AND d.project_id IN (SELECT project_id FROM visible_direct_projects)) OR (EXISTS (SELECT 1 FROM visible_related_devices) AND d.sn IN (SELECT device_sn FROM visible_related_devices)) OR (EXISTS (SELECT 1 FROM visible_device_contracts) AND CAST(d.contract_no AS BINARY) IN (SELECT contract_key FROM visible_device_contracts))) AND d.tenant_id = 1 ORDER BY d.id DESC LIMIT 0, 10), page_device_keys AS (SELECT DISTINCT sn FROM device_page), renewal_counts AS (SELECT wr.tenant_id, wr.device_sn, COUNT(*) AS extended_count FROM page_device_keys k JOIN ast_device_warranty_record wr ON wr.tenant_id = 1 AND wr.device_sn = k.sn AND wr.tenant_id = 1 WHERE wr.deleted = B'0' AND wr.extended = B'1' GROUP BY wr.tenant_id, wr.device_sn) SELECT p.*, COALESCE(rc.extended_count, 0) AS extended_count, totals.total FROM device_totals totals LEFT JOIN device_page p ON 1 = 1 LEFT JOIN renewal_counts rc ON rc.tenant_id = 1 AND rc.device_sn = p.sn ORDER BY p.device_id DESC;
